import zipfile, re, copy, difflib
from lxml import etree
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML = "http://www.w3.org/XML/1998/namespace"
def q(t): return "{%s}%s" % (W, t)
AUTHOR = "Greenleaf Counsel"
DATE = "2025-05-12T09:00:00Z"
_id = [1000]
def nid():
    _id[0] += 1
    return str(_id[0])

class Doc:
    def __init__(self, path):
        self.path = path
        z = zipfile.ZipFile(path)
        self.files = {n: z.read(n) for n in z.namelist()}
        self.root = etree.fromstring(self.files["word/document.xml"])
        self.body = self.root.find(q("body"))
        self.paras = [p for p in self.body if p.tag == q("p")]
        self.comments = []
        # base rPr from a plain body run
        self.base_rpr = None
        for p in self.paras:
            rs = p.findall(q("r"))
            if len(rs) == 1 and rs[0].find(q("rPr")) is not None and rs[0].find(q("rPr")).find(q("b")) is None and (rs[0].findtext(q("t")) or "").strip():
                self.base_rpr = copy.deepcopy(rs[0].find(q("rPr"))); break

    def rpr(self, bold=False, src=None):
        r = copy.deepcopy(src if src is not None else self.base_rpr)
        b = r.find(q("b"))
        if bold and b is None:
            rf = r.find(q("rFonts"))
            nb = etree.Element(q("b"))
            if rf is not None: rf.addnext(nb)
            else: r.insert(0, nb)
        if not bold and b is not None and src is None:
            r.remove(b)
        return r

    def _run(self, text, rpr, deleted=False):
        r = etree.Element(q("r"))
        r.append(copy.deepcopy(rpr))
        t = etree.SubElement(r, q("delText" if deleted else "t"))
        t.text = text
        t.set("{%s}space" % XML, "preserve")
        return r

    def _wrap(self, kind, run):
        w = etree.Element(q(kind))
        w.set(q("id"), nid()); w.set(q("author"), AUTHOR); w.set(q("date"), DATE)
        w.append(run)
        return w

    def ins_run(self, text, rpr):
        return self._wrap("ins", self._run(text, rpr))
    def del_run(self, text, rpr):
        return self._wrap("del", self._run(text, rpr, deleted=True))

    def modify(self, idx, new_text, run_index=None):
        p = self.paras[idx]
        runs = p.findall(q("r"))
        if run_index is None:
            run_index = len(runs) - 1
        run = runs[run_index]
        rpr = run.find(q("rPr"))
        old = "".join(t.text or "" for t in run.findall(q("t")))
        tok = lambda s: re.findall(r"\s+|[\w$.,%()\-]+|[^\w\s]", s)
        a, b = tok(old), tok(new_text)
        assert "".join(a) == old and "".join(b) == new_text
        sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
        out = []
        ops = sm.get_opcodes()
        # merge tiny equal islands (single whitespace) between changes for readability
        merged = []
        for op in ops:
            merged.append(list(op))
        res = []
        i = 0
        while i < len(merged):
            tag, i1, i2, j1, j2 = merged[i]
            if tag == "equal" and 0 < i < len(merged)-1 and (i2 - i1) <= 2 and "".join(a[i1:i2]).strip() == "" :
                # absorb into replace
                prev = res[-1] if res else None
                res.append(["replace", i1, i2, j1, j2])
            else:
                res.append([tag, i1, i2, j1, j2])
            i += 1
        # coalesce consecutive non-equal ops
        co = []
        for op in res:
            if co and op[0] != "equal" and co[-1][0] != "equal":
                co[-1] = ["replace", co[-1][1], op[2], co[-1][3], op[4]]
            else:
                co.append(op)
        for tag, i1, i2, j1, j2 in co:
            if tag == "equal":
                out.append(self._run("".join(a[i1:i2]), rpr))
            else:
                if i2 > i1: out.append(self.del_run("".join(a[i1:i2]), rpr))
                if j2 > j1: out.append(self.ins_run("".join(b[j1:j2]), rpr))
        parent = run.getparent(); pos = parent.index(run)
        parent.remove(run)
        for k, e in enumerate(out):
            parent.insert(pos + k, e)

    def mark_para_ins(self, p):
        ppr = p.find(q("pPr"))
        if ppr is None:
            ppr = etree.SubElement(p, q("pPr")); p.insert(0, ppr)
        r = ppr.find(q("rPr"))
        if r is None: r = etree.SubElement(ppr, q("rPr"))
        m = etree.SubElement(r, q("ins")); m.set(q("id"), nid()); m.set(q("author"), AUTHOR); m.set(q("date"), DATE)

    def new_para(self, ref_idx, segments, indent=None):
        ref = self.paras[ref_idx]
        p = etree.Element(q("p"))
        ppr = copy.deepcopy(ref.find(q("pPr")))
        for c in list(ppr):
            if c.tag in (q("rPr"),): ppr.remove(c)
        ind = ppr.find(q("ind"))
        if indent is not None:
            if ind is None:
                ind = etree.Element(q("ind"))
                jc = ppr.find(q("jc"))
                if jc is not None: jc.addprevious(ind)
                else: ppr.append(ind)
            ind.set(q("left"), str(indent))
        elif indent is None and ind is not None and getattr(self, "_noindent", False):
            ppr.remove(ind)
        p.append(ppr)
        self.mark_para_ins(p)
        for seg in segments:
            if isinstance(seg, str): seg = (seg, False)
            text, bold = seg
            p.append(self.ins_run(text, self.rpr(bold=bold)))
        return p

    def insert_after(self, anchor, ref_idx, paras_spec):
        """anchor: element after which to insert; paras_spec list of (segments, indent). returns last element"""
        cur = anchor
        for segs, indent in paras_spec:
            np_ = self.new_para(ref_idx, segs, indent)
            cur.addnext(np_); cur = np_
        return cur

    def delete_para(self, idx):
        p = self.paras[idx]
        for run in p.findall(q("r")):
            for t in run.findall(q("t")):
                t.tag = q("delText"); t.set("{%s}space" % XML, "preserve")
            w = etree.Element(q("del")); w.set(q("id"), nid()); w.set(q("author"), AUTHOR); w.set(q("date"), DATE)
            run.addprevious(w); w.append(run)
        ppr = p.find(q("pPr"))
        r = ppr.find(q("rPr"))
        if r is None: r = etree.SubElement(ppr, q("rPr"))
        m = etree.SubElement(r, q("del")); m.set(q("id"), nid()); m.set(q("author"), AUTHOR); m.set(q("date"), DATE)

    def comment(self, p, text):
        cid = str(len(self.comments))
        self.comments.append((cid, text))
        ppr = p.find(q("pPr"))
        s = etree.Element(q("commentRangeStart")); s.set(q("id"), cid)
        if ppr is not None: ppr.addnext(s)
        else: p.insert(0, s)
        e = etree.SubElement(p, q("commentRangeEnd")); e.set(q("id"), cid)
        r = etree.SubElement(p, q("r"))
        rp = etree.SubElement(r, q("rPr")); rs = etree.SubElement(rp, q("rStyle")); rs.set(q("val"), "CommentReference")
        cr = etree.SubElement(r, q("commentReference")); cr.set(q("id"), cid)

    def save(self, out):
        self.files["word/document.xml"] = etree.tostring(self.root, xml_declaration=True, encoding="UTF-8", standalone=True)
        if self.comments:
            croot = etree.Element(q("comments"), nsmap={"w": W})
            for cid, text in self.comments:
                c = etree.SubElement(croot, q("comment")); c.set(q("id"), cid); c.set(q("author"), AUTHOR); c.set(q("date"), DATE); c.set(q("initials"), "GC")
                for k, para in enumerate(text.split("\n")):
                    pp = etree.SubElement(c, q("p"))
                    if k == 0:
                        rr = etree.SubElement(pp, q("r")); rp = etree.SubElement(rr, q("rPr")); st = etree.SubElement(rp, q("rStyle")); st.set(q("val"), "CommentReference")
                        etree.SubElement(rr, q("annotationRef"))
                    rr = etree.SubElement(pp, q("r")); t = etree.SubElement(rr, q("t")); t.text = para; t.set("{%s}space" % XML, "preserve")
            self.files["word/comments.xml"] = etree.tostring(croot, xml_declaration=True, encoding="UTF-8", standalone=True)
            ct = self.files["[Content_Types].xml"].decode()
            if "comments.xml" not in ct:
                ct = ct.replace("</Types>", '<Override PartName="/word/comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/></Types>')
                self.files["[Content_Types].xml"] = ct.encode()
            rels = self.files["word/_rels/document.xml.rels"].decode()
            if "comments.xml" not in rels:
                rels = rels.replace("</Relationships>", '<Relationship Id="rIdCmt1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/></Relationships>')
                self.files["word/_rels/document.xml.rels"] = rels.encode()
        z = zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED)
        order = ["[Content_Types].xml"] + [n for n in self.files if n != "[Content_Types].xml"]
        for n in order: z.writestr(n, self.files[n])
        z.close()
